<?php
/* Caminho: pages/assinatura.php */
declare(strict_types=1);
require dirname(__DIR__).'/includes/bootstrap.php';$pdo=arc_db();arc_ensure_user_schema($pdo);
if(!arc_is_user()){header('Location: '.arc_workspace_base_url().'index.php',true,303);exit;}
$uid=(int)arc_user_id();$error='';$notice='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{
  arc_verify_csrf();$action=(string)($_POST['action']??'');
  if($action==='checkout'){
   $i=arc_billing_invoice($pdo,$uid,(int)($_POST['plan_id']??0),(string)($_POST['provider']??''));$url=arc_billing_checkout($pdo,$i,(string)($_POST['document']??''));
   if($url!==''){header('Location: '.$url,true,303);exit;}$notice='Cobrança Pix criada. Confira a chave e registre a referência após pagar.';
  }elseif($action==='receipt'){
   $note=trim((string)($_POST['receipt_note']??''));if(mb_strlen($note)<8||mb_strlen($note)>255)throw new RuntimeException('Informe a referência da transação e o nome do pagador (8–255 caracteres).');
   $q=$pdo->prepare("UPDATE ".arc_table('billing_invoices')." SET receipt_note=?,status='review' WHERE id=? AND account_id=? AND provider='pix' AND status='pending'");$q->execute([$note,(int)($_POST['invoice_id']??0),$uid]);if(!$q->rowCount())throw new RuntimeException('Cobrança indisponível para conferência.');$notice='Referência enviada. O administrador deve conferir o recebimento antes de liberar o plano.';
  }elseif($action==='cancel_pix'){
   $pdo->prepare("UPDATE ".arc_table('billing_invoices')." SET status='cancelled' WHERE id=? AND account_id=? AND provider='pix' AND status='pending'")->execute([(int)($_POST['invoice_id']??0),$uid]);$notice='Cobrança Pix cancelada.';
  }elseif($action==='cancel_renewal'){
   $pdo->prepare('UPDATE '.arc_table('billing_subscriptions').' SET cancel_at_period_end=1 WHERE account_id=?')->execute([$uid]);$notice='Renovação cancelada. O período já pago será mantido.';
  }else throw new RuntimeException('Ação inválida.');
  $_SESSION['arc_flash']=$notice;header('Location: '.arc_workspace_base_url().'pages/assinatura.php',true,303);exit;
 }catch(RuntimeException $e){$error=$e instanceof PDOException?'Serviço indisponível. Verifique os registros do servidor.':$e->getMessage();}catch(Throwable $e){error_log('Assinatura: '.$e->getMessage());$error='Não foi possível concluir. Nenhum pagamento foi confirmado.';}
}
$plans=$pdo->query('SELECT * FROM '.arc_table('billing_plans').' WHERE enabled=1 ORDER BY price_cents,id')->fetchAll();$policy=arc_billing_policy($pdo,$uid);$usage=arc_billing_usage($pdo,$uid);$sub=arc_billing_subscription($pdo,$uid);
$q=$pdo->prepare('SELECT i.*,p.name FROM '.arc_table('billing_invoices').' i JOIN '.arc_table('billing_plans').' p ON p.id=i.plan_id WHERE i.account_id=? ORDER BY i.id DESC LIMIT 30');$q->execute([$uid]);$invoices=$q->fetchAll();
$ARCPageTitle='Planos e cobrança';$ARCActiveNav='billing';require dirname(__DIR__).'/includes/header.php';require dirname(__DIR__).'/includes/sidebar.php';
?>
<main class="app-main"><div class="page-content arc-service">
<header class="arc-service-heading"><div><h1>Planos e cobrança</h1><p>Mensalidades em reais, por conta. Escolha capacidade para sua operação.</p></div><span class="arc-service-pill"><?=arc_h($policy['name'])?> · <?=$policy['active']?'ativo':'regularização necessária'?></span></header>
<?php if($error):?><p class="arc-service-error" role="alert"><?=arc_h($error)?></p><?php endif;?>
<div class="arc-service-metrics"><?php foreach(['networks'=>'Redes ativas','agents'=>'Agentes aprovados','seats'=>'Técnicos adicionais'] as $k=>$label):?><article><small><?=arc_h($label)?></small><strong><?=$usage[$k]?> <small>/ <?=(int)$policy[$k.'_limit']?:'sem limite'?></small></strong></article><?php endforeach;?></div>
<?php if($sub):?><section class="arc-service-card"><h2>Sua assinatura</h2><p><?=arc_h($sub['name'])?> · <?=arc_money((int)$sub['price_cents'])?> a cada 30 dias. Período até <?=arc_h(arc_when($sub['period_end']))?>.</p><p>A renovação gera uma nova cobrança. Não há débito automático em cartão.</p><form method="post"><input type="hidden" name="_csrf" value="<?=arc_h(arc_csrf_token())?>"><input type="hidden" name="action" value="cancel_renewal"><button class="button" <?=$sub['cancel_at_period_end']?'disabled':''?>><?=$sub['cancel_at_period_end']?'Renovação cancelada':'Cancelar próxima renovação'?></button></form></section><?php endif;?>
<div class="arc-service-plans"><?php foreach($plans as $p):?><article class="arc-service-card"><h2><?=arc_h($p['name'])?></h2><p class="arc-plan-price"><?=arc_money((int)$p['price_cents'])?><small>/30 dias</small></p><ul><li><?=(int)$p['networks_limit']?:'Ilimitadas'?> redes</li><li><?=(int)$p['agents_limit']?:'Ilimitados'?> agentes</li><li><?=(int)$p['seats_limit']?:'Ilimitados'?> técnicos adicionais</li><li>Chamados, histórico e suporte remoto</li></ul><form method="post" class="arc-service-form"><input type="hidden" name="_csrf" value="<?=arc_h(arc_csrf_token())?>"><input type="hidden" name="action" value="checkout"><input type="hidden" name="plan_id" value="<?=(int)$p['id']?>"><label>Pagamento<select name="provider" required><option value="">Selecione</option><?php foreach(['mercadopago'=>'Mercado Pago','asaas'=>'Asaas','pix'=>'Pix manual'] as $k=>$label):if(arc_billing_setting($pdo,$k.'_enabled')==='1'):?><option value="<?=$k?>"><?=$label?></option><?php endif;endforeach;?></select></label><label>CPF/CNPJ (Asaas)<input name="document" inputmode="numeric" maxlength="18" autocomplete="off"></label><button class="button primary">Escolher plano</button></form></article><?php endforeach;?></div>
<section class="arc-service-card"><h2>Histórico de cobranças</h2><p>O retorno do checkout não confirma pagamento. A liberação depende da conciliação do gateway ou da conferência do Pix.</p><div class="arc-service-list"><?php foreach($invoices as $i):?><article><div><strong>#<?=(int)$i['id']?> · <?=arc_h($i['name'])?> · <?=arc_money((int)$i['amount_cents'])?></strong><p><?=arc_h(['pending'=>'Aguardando pagamento','processing'=>'Processamento / conciliação','review'=>'Em conferência','paid'=>'Pago','reversed'=>'Estornado / contestado','cancelled'=>'Cancelado'][$i['status']]??$i['status'])?> · <?=arc_h($i['provider'])?></p></div><?php if($i['checkout_url']&&$i['status']==='pending'&&arc_billing_safe_checkout($i['checkout_url'],$i['provider'])):?><a class="button primary" href="<?=arc_h($i['checkout_url'])?>" rel="noopener noreferrer">Pagar</a><?php endif;?><?php if($i['provider']==='pix'&&$i['status']==='pending'):?><div class="arc-service-card"><p>Chave Pix: <strong><?=arc_h(arc_billing_setting($pdo,'pix_key'))?></strong></p><p><?=arc_h(arc_billing_setting($pdo,'pix_instructions'))?></p><form method="post" class="arc-service-form"><input type="hidden" name="_csrf" value="<?=arc_h(arc_csrf_token())?>"><input type="hidden" name="invoice_id" value="<?=(int)$i['id']?>"><label>Referência da transação e nome do pagador<input name="receipt_note" maxlength="255"></label><button class="button" name="action" value="receipt">Enviar para conferência</button><button class="button" name="action" value="cancel_pix">Cancelar cobrança</button></form></div><?php endif;?></article><?php endforeach;?><?php if(!$invoices):?><p>Nenhuma cobrança registrada.</p><?php endif;?></div></section>
</div></main>
<?php require dirname(__DIR__).'/includes/footer.php';?>
